types-prim-001.example:
```js
const samples = [
  'hi',            // string
  42,              // number
  10n,             // bigint
  true,            // boolean
  undefined,       // undefined
  Symbol('id'),    // symbol
  null,            // null  -> but typeof reports 'object' (legacy bug)
  {},              // object (not primitive)
];

for (const v of samples) {
  console.log(String(v).padEnd(12), '->', typeof v);
}
// note: typeof null === 'object', yet null IS a primitive.
```
